{
  "name": "lpdev",
  "version": "0.1.1",
  "description": "Laravel Package Development CLI - Manage Laravel package development workflows with ease",
  "main": "index.js",
  "bin": {
    "lpdev": "./bin/lpdev"
  },
  "scripts": {
    "postinstall": "node scripts/postinstall.js",
    "test": "bash -n bin/lpdev"
  },
  "keywords": [
    "laravel",
    "package",
    "development",
    "cli",
    "workflow",
    "composer"
  ],
  "author": {
    "name": "Dima Botezatu",
    "email": "dima@inovector.com"
  },
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/inovector/lpdev.git"
  },
  "bugs": {
    "url": "https://github.com/inovector/lpdev/issues"
  },
  "homepage": "https://github.com/inovector/lpdev#readme",
  "engines": {
    "node": ">=14.0.0"
  },
  "os": [
    "darwin",
    "linux"
  ],
  "files": [
    "bin/",
    "lib/",
    "scripts/",
    "index.js",
    "README.md",
    "LICENSE"
  ],
  "preferGlobal": true
}

#!/usr/bin/env node

function main() {
  console.log('\n📦 Installing lpdev...\n');

  if (process.platform === 'win32') {
    console.log('⚠ Windows is not fully supported. Some features may not work correctly.');
    return;
  }

  console.log('\n✅ lpdev installed successfully!');
  console.log('\nGet started with: lpdev --help\n');
}

if (require.main === module) {
  main();
}

#!/usr/bin/env node

console.log('lpdev is a bash CLI tool. Use "lpdev --help" for more information.');
process.exit(0);
